
bin_list = []

def representation(maze: list[list[list[int]]]) -> None:
    for row in maze:
        line = ""
        for block in row:
            if block[3] == 1:
                line += "=="
            else:
                line += " "
            if block[2] == 1:
                line += "=="
            else:
                line += "||"
            if block[1] == 1:
                line += "=="
            else:
                line += " "    
            if block[0] == 1:
                line += "||" 
            else:
                line += " "
        print(line)


def hexatodectobin(maze: list[list[list[int]]]) -> None:
    for row in maze:
        bin_row = []
        for number in row:
            decimal_num = int(number, 16)
            bin_num = format(decimal_num, "04b")
            bin_row.append(bin_num)
        bin_list.append(bin_row)
    print(bin_list)
    return bin_list


